// Package apidoc registers the doc comments the generated OpenAPI document
// describes a project's API with.
//
// Code generated by gg registers struct, field and enum comments at build
// time, in model/apidoc.gen.go, so the running binary can describe schema
// fields even when Go source files are not available, eg. in a container
// image that only ships the compiled binary. A way requests authenticate is
// declared through RegisterSecurityScheme, and a project words the summary
// and description of an operation itself through RegisterOperation.
//
// The implementation lives in internal/apidoc; this package forwards the part
// a project uses.
package apidoc

import "github.com/hydroan/gst/internal/apidoc"

// StructDoc holds the doc comments of a single struct: Comment is the doc
// comment of the struct itself, and Fields maps a Go field name to its doc
// comment.
type StructDoc = apidoc.StructDoc

// EnumValue describes one declared constant of an enum-like named type: Value
// is the constant literal as it appears in JSON, eg. "active" or 2, and
// Comment is the doc comment of the constant.
type EnumValue = apidoc.EnumValue

// EnumDoc holds the doc comment and declared values of an enum-like named
// type, eg. `type SampleStatus string` with a const block of its values:
// Comment is the doc comment of the type itself, and Values lists the
// declared constants in source order.
type EnumDoc = apidoc.EnumDoc

// SecurityScheme is one way a request authenticates, as the OpenAPI document
// declares it under components.securitySchemes: Type is apiKey or http; In
// and Name place an apiKey, the cookie and its name for a session cookie;
// Scheme names an http scheme, bearer for a token; Description tells the
// reader where the credential comes from.
type SecurityScheme = apidoc.SecurityScheme

// OperationDoc holds an explicit summary and description for one operation:
// Summary and Description each override, when non-empty, what the document
// derives for the operation.
type OperationDoc = apidoc.OperationDoc

// Register records the doc comments for the struct identified by pkgPath and
// typeName. Registering the same struct again replaces the previous entry.
// The Fields map is copied, so callers may reuse it after Register returns.
func Register(pkgPath, typeName string, doc StructDoc) { apidoc.Register(pkgPath, typeName, doc) }

// RegisterEnum records the doc comment and declared values of the enum-like
// type identified by pkgPath and typeName. Registering the same type again
// replaces the previous entry. The Values slice is copied, so callers may
// reuse it after RegisterEnum returns.
func RegisterEnum(pkgPath, typeName string, doc EnumDoc) { apidoc.RegisterEnum(pkgPath, typeName, doc) }

// RegisterSecurityScheme records, under the component name given, a way a
// request authenticates. The document declares the registered schemes and no
// other, and requires any one of them of every operation not declared
// public. Registering a name again replaces the previous scheme.
func RegisterSecurityScheme(name string, scheme SecurityScheme) {
	apidoc.RegisterSecurityScheme(name, scheme)
}

// RegisterOperation records an explicit summary/description for the operation
// identified by its HTTP method and route path. Registering the same
// operation again replaces the previous entry. The path accepts both
// gin-style ":param" and OpenAPI-style "{param}" placeholders.
func RegisterOperation(method, path string, doc OperationDoc) {
	apidoc.RegisterOperation(method, path, doc)
}
